class RerankerEvaluator:
    def rank_documents(self, query: str, corpus: list[str],
                       score_fn) -> list[int]:
        scores = [score_fn(query, doc) for doc in corpus]
        return sorted(range(len(corpus)), key=lambda i: scores[i], reverse=True)

    def mrr(self, ranked_ids: list[int], relevant_ids: set[int]) -> float:
        for rank, doc_id in enumerate(ranked_ids, start=1):
            if doc_id in relevant_ids:
                return 1.0 / rank
        return 0.0

    def compare(self, queries: list[str], corpus: list[str],
                relevant_map: list[set[int]],
                generic_fn, finetuned_fn) -> dict:
        n = len(queries)
        generic_total = 0.0
        finetuned_total = 0.0
        for q, rel in zip(queries, relevant_map):
            generic_total += self.mrr(self.rank_documents(q, corpus, generic_fn), rel)
            finetuned_total += self.mrr(self.rank_documents(q, corpus, finetuned_fn), rel)
        generic_mrr = generic_total / n if n else 0.0
        finetuned_mrr = finetuned_total / n if n else 0.0
        if generic_mrr == 0:
            improvement = 0.0
        else:
            improvement = (finetuned_mrr - generic_mrr) / generic_mrr * 100
        return {"generic_mrr": generic_mrr,
                "finetuned_mrr": finetuned_mrr,
                "improvement_pct": improvement}


# Test it:
ev = RerankerEvaluator()

corpus = ["doc_a", "doc_b", "doc_c", "doc_d"]

def generic_fn(query, doc):
    return corpus.index(doc)

def finetuned_fn(query, doc):
    return 10.0 if doc in ["doc_a", "doc_c"] else 1.0

ranked = ev.rank_documents("test", corpus, generic_fn)
print(ranked[0])

print(ev.mrr([3, 2, 0, 1], {0, 1}))

result = ev.compare(
    ["q1", "q2"], corpus,
    [{0}, {2}],
    generic_fn, finetuned_fn)
print(f"{result['generic_mrr']:.4f}")
print(f"{result['finetuned_mrr']:.4f}")
print(result['finetuned_mrr'] > result['generic_mrr'])
